import json, pathlib
from playwright.sync_api import sync_playwright
RAIZ = pathlib.Path(__file__).resolve().parent.parent
url = (RAIZ / "site" / "index.html").as_uri(); P = json.load(open(RAIZ / "dados" / "painel.json", encoding="utf-8")); iu = P["meses"].index(P["ultimo_mes_completo"])
erros = []
with sync_playwright() as p:
    nav = p.chromium.launch(channel="chrome", headless=True); pg = nav.new_page(viewport={"width": 1280, "height": 900})
    pg.on("console", lambda m: erros.append(f"console.{m.type}: {m.text}") if m.type in ("error", "warning") else None); pg.on("pageerror", lambda e: erros.append(f"pageerror: {e}"))
    pg.goto(url); pg.wait_for_selector("#arvore details.g")
    print("abas:", pg.locator(".abas button").all_inner_texts())
    # ---- Alertas na Visão geral: etiquetas nas equipes e filtro "Mostrar"
    falhas = []
    def conf(nome, ok, det=""):
        print(("OK   " if ok else "FALHA"), nome, ("| " + str(det)) if det != "" else "")
        if not ok: falhas.append(nome)
    conf("abas Prioridades e Alertas removidas; 1ª aba é Visão geral", pg.inner_text("#aba-p") == "Perfil dos atendimentos" and pg.locator("#aba-a").count() == 0 and pg.inner_text("#aba-h") == "Visão geral")
    conf("sem filtro: 16 GSAPs, fechadas", pg.locator("#arvore > details.g").count() == 16 and pg.locator("#arvore > details.g[open]").count() == 0)
    conf("GSAP mostra quantas equipes têm alerta", pg.locator("#arvore > details.g .sinais .chip.conta").count() > 0, pg.locator("#arvore > details.g .sinais .chip.conta").first.inner_text())
    pg.select_option("#f-alerta", "*"); pg.wait_for_timeout(900)
    n_eq = pg.locator("#arvore details.e").count(); com = pg.locator("#arvore details.e:has(.sinais .chip)").count()
    conf("filtro 'com algum alerta': só equipes com etiqueta, já visíveis", n_eq > 0 and n_eq == com and pg.locator("#arvore details.e").first.is_visible(), f"{n_eq} equipes | {pg.inner_text('#f-resumo')[:60]}")
    pg.screenshot(path=str(RAIZ / "testes" / "shot_prio.png"))
    pg.select_option("#f-alerta", "alta"); pg.wait_for_timeout(900)
    n_alta = pg.locator("#arvore details.e").count(); com_alta = pg.locator("#arvore details.e:has(.sinais .chip.alta)").count()
    conf("filtro 'prioridade alta': todas com etiqueta vermelha", 0 < n_alta == com_alta and n_alta <= n_eq, f"{n_alta} equipes")
    pg.select_option("#f-alerta", "acs"); pg.wait_for_timeout(900)
    n_acs = pg.locator("#arvore details.e").count(); esperado = sum(1 for a in P["alertas"] if a["tipo"] == "ACS sem visita")
    conf("filtro por tipo (ACS sem visita) = alertas do JSON", n_acs == esperado, f"tela {n_acs} | JSON {esperado}")
    pg.locator("#arvore details.e .sinais .chip").first.hover(); pg.wait_for_timeout(150)
    conf("dica da etiqueta traz o detalhe do alerta", "ACS" in pg.evaluate("document.getElementById('dica').innerText"), pg.evaluate("document.getElementById('dica').innerText")[:70])
    pg.locator("#arvore details.e > summary").first.click(); pg.wait_for_timeout(300)
    conf("equipe filtrada abre normalmente", pg.locator("#arvore details.e[open] table").count() >= 1)
    pg.select_option("#f-alerta", ""); pg.wait_for_timeout(300)
    conf("tirar o filtro volta às 16 GSAPs", pg.locator("#arvore > details.g").count() == 16)
    pg.select_option("#f-alerta", "alta"); pg.wait_for_timeout(600); pg.click("#aba-h"); pg.click("#f-barra .abrir-cmp"); pg.wait_for_selector("#vista-c circle.pt"); pg.locator("#vista-c circle.pt").first.click(); pg.wait_for_timeout(500)
    conf("ir para uma equipe fora do filtro desliga o filtro e abre a equipe", pg.locator("#vista-h").is_visible() and pg.locator("details.e[open]").count() >= 1, "filtro agora: '" + pg.input_value("#f-alerta") + "'")
    pg.select_option("#f-alerta", ""); pg.wait_for_timeout(200)
    # ---- Seletor de indicador em dois passos e comparação dentro dos cards
    conf("10 grupos de indicador (boas práticas); aba Comparar virou botão", pg.locator("#grp-ind button").count() == 10 and pg.locator("#aba-c").count() == 0, " | ".join(pg.locator("#grp-ind button").all_inner_texts()))
    n_ind = len(P["indicadores"]); soma = 0
    for g in ["prod", "inf", "gest", "dm", "has", "idoso", "mulher", "bucal", "outras", "mot"]:
        pg.click(f"#grp-ind button[data-g='{g}']"); pg.wait_for_timeout(250); soma += pg.locator("#sel-ind option").count()
        conf(f"grupo {g}: botão marcado e título do gráfico acompanha", pg.get_attribute(f"#grp-ind button[data-g='{g}']", "aria-pressed") == "true" and pg.inner_text("#sel-ind option:checked").replace("— ", "").replace(" (só por equipe)", "") in pg.inner_text("#tit-graf"), pg.inner_text("#tit-graf"))
    conf("os grupos cobrem todos os indicadores (um indicador pode estar em mais de um grupo)", soma >= n_ind, f"{soma} entradas para {n_ind} indicadores")
    pg.click("#grp-ind button[data-g='prod']"); pg.wait_for_timeout(200)
    conf("odontologia fica em Saúde bucal, não em Acesso e produção", pg.locator("#sel-ind option[value='odonto1']").count() == 0)
    pg.select_option("#sel-ind", "visitas"); pg.click("#grp-ind button[data-g='gest']"); pg.click("#grp-ind button[data-g='prod']"); pg.wait_for_timeout(200)
    conf("voltar ao grupo lembra o último indicador usado nele", pg.input_value("#sel-ind") == "visitas")
    pg.click(".kpi[data-k='prenatal']"); pg.wait_for_timeout(250)
    conf("cartão do topo de outro grupo troca o grupo", pg.get_attribute("#grp-ind button[data-g='gest']", "aria-pressed") == "true" and pg.input_value("#sel-ind") == "prenatal")
    pg.click(".kpi[data-k='atend']"); pg.wait_for_timeout(250)
    pg.locator("#arvore > details.g > summary").first.click(); pg.wait_for_timeout(300)
    g0 = P["gsaps"][0]; esf_g0 = sum(1 for u in g0["ubs"] for e in u["equipes"] if e["ine"] and e["tipo"] == "eSF" and not e.get("migrou") and e["serie"].get("atend") and any(e["serie"]["atend"][max(iu - 11, 0):iu + 1]))
    conf("card da GSAP: um ponto por eSF contra a Região", pg.locator("#g0 > .corpo > .cmp-card circle.pt").count() == esf_g0, f"{esf_g0} equipes")
    pg.locator("#g0u0 > summary").click(); pg.wait_for_timeout(300)
    u0 = g0["ubs"][0]; esf_u0 = sum(1 for e in u0["equipes"] if e["ine"] and e["tipo"] == "eSF" and not e.get("migrou") and e["serie"].get("atend") and any(e["serie"]["atend"][max(iu - 11, 0):iu + 1]))
    conf("card da UBS: um ponto por eSF da UBS", pg.locator("#g0u0 > .corpo > .cmp-card circle.pt").count() == esf_u0, f"{esf_u0} equipes")
    pg.locator("#g0u0 > .corpo > .cmp-card circle.pt").first.hover(); pg.wait_for_timeout(150)
    conf("ponto do card tem dica com o número", "mediana da Região" in pg.evaluate("document.getElementById('dica').innerText"), pg.evaluate("document.getElementById('dica').innerText")[:80])
    pg.screenshot(path=str(RAIZ / "testes" / "shot_cmp_card.png"))
    pg.locator("#g0u0 > .corpo > .cmp-card circle.pt").first.click(); pg.wait_for_timeout(400)
    conf("clique no ponto do card abre a equipe", pg.locator("#g0u0 details.e[open]").count() >= 1)
    pg.locator("#g0u0 > .corpo > .cmp-card button.abrir-cmp").click(); pg.wait_for_timeout(400)
    conf("botão 'Ver comparação detalhada' abre a vista regional já na GSAP", pg.locator("#vista-c").is_visible() and pg.input_value("#cmp-gsap") == g0["nome"] and pg.get_attribute("#aba-h", "aria-selected") == "true")
    pg.click("#cmp-voltar"); pg.wait_for_timeout(300)
    conf("'Voltar à Visão geral' volta", pg.locator("#vista-h").is_visible() and not pg.locator("#vista-c").is_visible())
    pg.locator("#g0 > summary").click(); pg.wait_for_timeout(200)
    # ---- Vários motivos de consulta na mesma unidade
    conf("abas: Visão geral, Mapa de calor, Perfil dos atendimentos, Inconsistências", pg.locator("nav.abas button").all_inner_texts() == ["Visão geral", "Mapa de calor", "Perfil dos atendimentos", "Inconsistências"], pg.locator("nav.abas button").all_inner_texts())
    conf("fora de Motivos, a marcação múltipla não aparece", not pg.locator("#multi").is_visible())
    pg.click("#grp-ind button[data-g='mot']"); pg.wait_for_timeout(250); pg.select_option("#sel-ind", "m_has")
    conf("em Motivos aparece 'Comparar com outros motivos'", pg.locator("#multi").is_visible() and pg.locator("#multi-itens input").count() == 30, pg.inner_text("#multi-rot"))
    pg.click("#multi-rot"); pg.check("#multi-itens input[value='m_dm']"); pg.check("#multi-itens input[value='m_mental']"); pg.wait_for_timeout(300)
    conf("Região: gráfico com os 3 motivos e tabela", pg.locator("#graf-regiao .multi-graf tbody tr").count() == 3 and "Comparando 3 motivos" in pg.inner_text("#multi-rot"), pg.inner_text("#multi-rot"))
    v_dm = P["regiao"]["m_dm"][iu]
    conf("número da tabela = JSON (diabetes na Região)", f"{v_dm:,}".replace(",", ".") in pg.inner_text("#graf-regiao .multi-graf tbody tr:nth-child(2)"), v_dm)
    conf("o motivo principal fica marcado e travado na lista", pg.is_checked("#multi-itens input[value='m_has']") and pg.is_disabled("#multi-itens input[value='m_has']"))
    pg.click("h1"); pg.wait_for_timeout(150)
    conf("clicar fora fecha a lista", pg.locator("#multi[open]").count() == 0)
    pg.locator("#arvore > details.g > summary").first.click(); pg.wait_for_timeout(300); pg.locator("#g0u0 > summary").click(); pg.wait_for_timeout(300); pg.locator("#g0u0 details.e > summary").first.click(); pg.wait_for_timeout(300)
    conf("GSAP, UBS e equipe abertas mostram os motivos comparados", pg.locator("#g0 > .corpo > .multi-graf").count() == 1 and pg.locator("#g0u0 > .corpo > .multi-graf").count() == 1 and pg.locator("#g0u0 details.e[open] > .corpo > .multi-graf").count() == 1)
    pg.locator("#g0u0 > .corpo > .multi-graf rect.col").nth(5).hover(force=True); pg.wait_for_timeout(150)
    conf("dica do mês traz os 3 motivos", pg.evaluate("document.getElementById('dica').innerText").count(":") >= 3, pg.evaluate("document.getElementById('dica').innerText").replace("\n", " | ")[:120])
    pg.screenshot(path=str(RAIZ / "testes" / "shot_multi_motivos.png"))
    pg.click("#multi-rot"); [pg.check(f"#multi-itens input[value='{k}']") for k in ("m_resp_ag", "m_arbo", "m_gravidez")]; pg.wait_for_timeout(200)
    conf("limite: com 5 marcados os demais travam", pg.is_disabled("#multi-itens input[value='m_osteo']") and pg.locator("#graf-regiao .multi-graf tbody tr").count() == 6)
    pg.click("#multi-limpar"); pg.wait_for_timeout(300)
    conf("Limpar tira os gráficos de comparação", pg.locator(".multi-graf").count() == 0)
    pg.locator("#g0 > summary").click(); pg.click("#grp-ind button[data-g='prod']"); pg.wait_for_timeout(250); pg.select_option("#sel-ind", "atend"); pg.wait_for_timeout(200)
    # ---- Comparar
    pg.click("#aba-h"); pg.click("#f-barra .abrir-cmp"); pg.wait_for_selector("#vista-c circle.pt")
    n_esf = sum(1 for g in P["gsaps"] for u in g["ubs"] for e in u["equipes"] if e["ine"] and e["tipo"] == "eSF" and e["serie"].get("atend") and any(e["serie"]["atend"][max(iu - 11, 0):iu + 1]))
    print("COMPARAR: pontos", pg.locator("#vista-c circle.pt").count(), "| eSF com dados", n_esf, "| nota:", pg.locator("#cmp-nota").inner_text()[:110])
    pg.screenshot(path=str(RAIZ / "testes" / "shot_comparar.png"))
    pg.select_option("#sel-ind", "visitas"); pg.wait_for_timeout(200); print("  indicador visitas -> pontos", pg.locator("#vista-c circle.pt").count())
    pg.select_option("#sel-ind", "atend"); pg.select_option("#cmp-gsap", "GSAP 1 Planaltina"); pg.wait_for_timeout(150); print("  filtro GSAP 1 PLA -> pontos", pg.locator("#vista-c circle.pt").count())
    pg.select_option("#cmp-gsap", ""); pg.select_option("#cmp-modo", "3m"); pg.wait_for_timeout(150); print("  média 3 meses ok:", pg.locator("#vista-c circle.pt").count())
    pg.locator("#vista-c circle.pt").first.click(); pg.wait_for_timeout(300); print("  clique no ponto abre a equipe:", pg.locator("#vista-h").is_visible())
    # ---- Acesso
    pg.click("#aba-p"); pg.click("#aba-x"); pg.wait_for_selector("button.x-barra, .x-barra"); r = P["regiao"]
    print("ACESSO: seletor de indicador desabilitado:", pg.locator("#sel-ind").is_disabled(), "| linhas:", pg.locator(".x-barra").count())
    esperado = round(r["a_dia"][iu] / r["atend"][iu] * 100); print("  total da Região % no dia na tela:", pg.locator(".x-barra.total").inner_text().replace("\n", " ")[:120], "| esperado", esperado, "%")
    pg.screenshot(path=str(RAIZ / "testes" / "shot_acesso.png"))
    pg.select_option("#x-ord", "urg"); pg.wait_for_timeout(120); print("  ordenado por urgência, 1ª linha:", pg.locator("button.x-barra").first.inner_text().replace("\n", " | ")[:100])
    pg.locator("button.x-barra").first.click(); pg.wait_for_timeout(150); print("  desceu p/ GSAP:", pg.locator("#x-crumb").inner_text(), "| filhos:", pg.locator("button.x-barra").count())
    pg.locator("button.x-barra").first.click(); pg.wait_for_timeout(150); print("  desceu p/ UBS:", pg.locator("#x-crumb").inner_text().replace("\n", " "), "| equipes:", pg.locator(".x-barra").count() - 2)
    pg.select_option("#x-mes", str(iu - 12)); pg.wait_for_timeout(150); print("  mês trocado p/", P["meses"][iu - 12], "| cabeçalho:", pg.locator(".x-cab span").first.inner_text())
    pg.locator("#x-crumb button").first.click(); pg.wait_for_timeout(150); print("  voltou p/ Região:", pg.locator("#x-crumb").inner_text())
    pg.select_option("#x-mes", str(iu)); pg.wait_for_timeout(100)
    # ---- celular
    m = nav.new_page(viewport={"width": 390, "height": 800}); m.goto(url); m.wait_for_selector("#arvore details.g")
    m.select_option("#f-alerta", "*"); m.wait_for_timeout(700); print("celular Visão geral com filtro: rolagem lateral da PÁGINA =", m.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")); m.screenshot(path=str(RAIZ / "testes" / "_dicas" / "filtro_celular.png")); m.select_option("#f-alerta", "")
    m.locator("#arvore > details.g > summary").first.click(); m.wait_for_timeout(300); m.locator("#g0u0 > summary").click(); m.wait_for_timeout(300); print("celular card com comparação: rolagem lateral da PÁGINA =", m.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")); m.screenshot(path=str(RAIZ / "testes" / "_dicas" / "cmp_card_celular.png"))
    m.click("#grp-ind button[data-g='mot']"); m.wait_for_timeout(200); m.click("#multi-rot"); m.check("#multi-itens input[value='m_dm']"); m.wait_for_timeout(300); print("celular motivos comparados: rolagem lateral da PÁGINA =", m.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")); m.screenshot(path=str(RAIZ / "testes" / "_dicas" / "multi_celular.png")); m.click("#multi-limpar"); m.click("#grp-ind button[data-g='prod']"); m.wait_for_timeout(200)
    m.click("#f-barra .abrir-cmp"); m.wait_for_timeout(300); print("celular comparação detalhada: rolagem lateral da PÁGINA =", m.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth"))
    for aba in ("p", "m"):
        m.click(f"#aba-{aba}"); m.wait_for_timeout(250); print(f"celular aba {aba}: rolagem lateral da PÁGINA =", m.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth"))
    m.click("#aba-p"); m.click("#aba-x"); m.wait_for_timeout(200); m.screenshot(path=str(RAIZ / "testes" / "shot_acesso_celular.png"))
    nav.close()
print("ERROS:", erros if erros else "nenhum"); print("FALHAS:", falhas if falhas else "nenhuma")
